 q<-list(stem=stem,seed=seed,origin='synthetic',width_mm=width,height_mm=height,figure_family='multipanel',figure_task='integrated-evidence',plot_data_files=as.list(files),source=loc[[key]],data_origin=origin,palette=as.list(palette),observations=obs,numeric=numeric,extra_labels=extra_labels)
