# Native Hilbert mapping retained explicitly: one vector square per 10-kb input bin.
set.seed(seed);pdf(NULL);hc<-HilbertCurve::HilbertCurve(0,4095,level=6,mode='pixel');dev.off()
xy<-rbind(hc@POS[,c('x1','y1')],setNames(tail(hc@POS[,c('x2','y2')],1),c('x1','y1')));names(xy)<-c('x','y')
stopifnot(nrow(xy)==4096,!anyDuplicated(xy),all(abs(diff(xy$x))+abs(diff(xy$y))==1))
u<-(0:4095+.5)/4096;z<-.8*sin(2*pi*u*7)+.45*sin(2*pi*u*41)+rnorm(4096,0,.18)
a<-plogis(z);b<-plogis(z+1.7*exp(-((u-.3)/.08)^2)-1.6*exp(-((u-.73)/.065)^2));a[1700:1780]<-NA;b[1700:1780]<-NA
hd<-data.frame(bin=1:4096,start_bp=(0:4095)*10000,end_bp=(1:4096)*10000,x=xy$x,y=xy$y,condition_a=a,condition_b=b,delta=b-a,quarter=factor(rep(paste0('Q',1:4),each=1024),levels=paste0('Q',1:4)))
cols<-c(low='#F5F0DA',middle='#88B8AA',high='#245F61',negative='#74609E',zero='#F8F6F1',positive='#C88742',missing='#D1D4D7')
hplot<-function(v,title,tag,diverge=FALSE){
 d<-hd;d$value<-d[[v]];p<-ggplot(d,aes(x,y,fill=value))+geom_tile(width=1,height=1)+coord_fixed(xlim=c(-.5,63.5),ylim=c(-.5,63.5),expand=FALSE)+void+labs(title=title,tag=tag)+theme(legend.position='right',legend.key.width=unit(2.5,'mm'))
 if(diverge)p+geom_point(data=data.frame(x=NA_real_,y=NA_real_),aes(x,y,shape='Missing'),inherit.aes=FALSE,colour=cols['missing'],size=2,na.rm=TRUE)+scale_shape_manual(values=c(Missing=15),name=NULL)+scale_fill_gradient2(low=cols['negative'],mid=cols['zero'],high=cols['positive'],limits=c(-.5,.5),breaks=c(-.5,0,.5),na.value=cols['missing'],name='B - A',guide=guide_colourbar(barheight=unit(25,'mm'),nbin=128,display='rectangles'))else p+scale_fill_gradientn(colours=cols[1:3],limits=c(0,1),breaks=c(0,.5,1),na.value=cols['missing'],name='Score',guide=guide_colourbar(barheight=unit(25,'mm'),nbin=128,display='rectangles'))
}
qcols<-c(Q1='#DCE6E1',Q2='#A9C5C6',Q3='#C4B8CC',Q4='#DFCAB4');cent<-aggregate(cbind(x,y)~quarter,hd,mean)
pdf(NULL);coarse<-HilbertCurve::HilbertCurve(0,15,level=2,mode='pixel');dev.off();keypath<-rbind(coarse@POS[,c('x1','y1')],setNames(tail(coarse@POS[,c('x2','y2')],1),c('x1','y1')));names(keypath)<-c('x','y');keypath<-(keypath+.5)*16-.5
coord<-ggplot(hd,aes(x,y,fill=quarter))+geom_tile(width=1,height=1)+geom_path(data=keypath,aes(x,y),inherit.aes=FALSE,colour='#68747B',linewidth=.3,arrow=arrow(length=unit(1.2,'mm'),ends='last'))+geom_point(data=keypath[1,],aes(x,y),inherit.aes=FALSE,colour='#68747B',size=1.3)+geom_text(data=cent,aes(label=quarter),colour='#35424B',family='Arial',size=7/.pt)+coord_fixed(xlim=c(-.5,63.5),ylim=c(-.5,63.5),expand=FALSE)+scale_fill_manual(values=qcols,labels=c('0-10.24','10.24-20.48','20.48-30.72','30.72-40.96'),name='Position (Mb)')+void+labs(title='Genomic coordinate key',tag='d')+theme(legend.position='right',legend.key.height=unit(3,'mm'),legend.key.width=unit(3,'mm'))
p<-wrap_plots(hplot('condition_a','Condition A','a'),hplot('condition_b','Condition B','b'),hplot('delta','Score difference','c',TRUE),coord,ncol=2)
savecase('HILBERT',p,hd,list(quarter_centers=cent),183,153,
 '固定种子模拟一条40.96Mb虚拟序列的4096个10kb窗口。HilbertCurve2.5.2原生6阶坐标逐格导出为向量矩形；两条件评分共用0-1尺度，差值直接B-A，81个连续窗口显式缺失并显示灰色。右下四区块提供线性坐标解码；仅为基因组坐标绘图示例，不代表真实染色体或生物学变化。',c(cols,qcols),
 list(hierarchy='Four aligned folded-coordinate maps:two conditions,exactB-A difference,andfour-quarter coordinate key.',geometry='Native order6Hilbert mapping gives64x64unit squares with shared orientation;each bin hasoneunique coordinate andadjacent bins share anedge.',palette='Cream-to-teal identical absolute scale forA/B;plum-neutral-ochre difference scale centered onzero;missing bins gray;muted quarters encode position.',typography='7pt Arial titles/legends and9pt a-d tags at183x153mm;no tiny individual bin labels.',marks='4096vector squares perpanel;81missing bins remainNA,notzero;quarter centers arecomputedfromtheexactmapping.',annotation='Compact score scales andMb interval key identify semantics;no simulation footer or actual chromosome inference.'),list(bins=4096,grid=64,level=6,missing=81,bin_bp=10000),c('Condition A','Condition B','Score difference','Genomic coordinate key'))

# Actual Morlet transforms; no surrogate significance test or copied contours.
set.seed(seed);tt<-seq(0,63.75,by=.25);conds<-c('Condition A','Condition B');wd<-data.frame(time_h=rep(tt,2),condition=rep(conds,each=length(tt)),value=c(sin(2*pi*tt/6)+.55*sin(2*pi*tt/2)*exp(-((tt-20)/12)^2),sin(2*pi*cumsum(.25/(2+tt*.12)))+.65*sin(2*pi*tt/12)*exp(-((tt-42)/17)^2))+rnorm(512,0,.12))
wt<-lapply(conds,function(c)WaveletComp::analyze.wavelet(subset(wd,condition==c),'value',loess.span=0,dt=.25,dj=1/12,lowerPeriod=1,upperPeriod=16,make.pval=FALSE,verbose=FALSE));power<-list();means<-list();cone<-list()
for(k in 1:2){
 z<-wt[[k]];d<-expand.grid(period=z$Period,time_h=tt);d$power<-as.vector(z$Power);d$condition<-conds[k];d$log_period<-log2(d$period);power[[k]]<-d
 means[[k]]<-data.frame(period=z$Period,log_period=log2(z$Period),power=as.numeric(z$Power.avg),condition=conds[k]);cone[[k]]<-data.frame(time_h=z$coi.1-1,log_period=z$coi.2,condition=conds[k],boundary=seq_along(z$coi.1)%in%(3:(length(z$coi.1)-2)))
 stopifnot(max(abs(rowMeans(z$Power)-z$Power.avg))<1e-12)
}
wp<-do.call(rbind,power);wm<-do.call(rbind,means);wc<-do.call(rbind,cone);mx<-max(wp$power);pc<-c('#F6F1E6','#DEC3AD','#B58497','#785F8E','#3F436C');linecols<-c('Condition A'='#326A80','Condition B'='#B6674F');parts<-list()
for(k in 1:2){
 c<-conds[k];d<-subset(wd,condition==c);a<-ggplot(d,aes(time_h,value))+geom_line(colour=linecols[c],linewidth=.32)+scale_x_continuous(limits=c(0,63.75),breaks=c(0,16,32,48,64),expand=c(0,0))+scale_y_continuous(limits=c(-2,2),breaks=c(-1,0,1))+labs(x=NULL,y='Signal',title=c,tag=letters[(k-1)*3+1])+base+theme(axis.text.x=element_blank(),axis.ticks.x=element_blank())
 b<-ggplot(subset(wp,condition==c),aes(time_h,log_period,fill=power))+geom_tile(width=.25,height=1/12)+geom_polygon(data=subset(wc,condition==c),aes(time_h,log_period),inherit.aes=FALSE,fill='#FFFFFF',alpha=.6,colour=NA)+geom_path(data=subset(wc,condition==c & boundary),aes(time_h,log_period,linetype='Edge-effect boundary'),inherit.aes=FALSE,colour='#8B8784',linewidth=.3)+scale_linetype_manual(values=c('Edge-effect boundary'='22'),name=NULL)+scale_fill_gradientn(colours=pc,limits=c(0,mx),name='Wavelet power',guide=guide_colourbar(barwidth=unit(48,'mm'),barheight=unit(2.5,'mm'),title.position='top',nbin=160,display='rectangles'))+scale_x_continuous(limits=c(-.125,63.875),breaks=c(0,16,32,48,64),expand=c(0,0))+scale_y_continuous(breaks=0:4,labels=c(1,2,4,8,16),expand=c(0,0))+coord_cartesian(ylim=c(-1/24,4+1/24),expand=FALSE)+labs(x='Time (h)',y='Period (h)',tag=letters[(k-1)*3+2])+base+theme(legend.position='bottom',axis.line=element_blank(),panel.border=element_rect(colour='#7D7B79',fill=NA,linewidth=.22))
 g<-ggplot(subset(wm,condition==c),aes(power,log_period))+geom_path(colour=linecols[c],linewidth=.6)+scale_y_continuous(breaks=0:4,labels=NULL,expand=c(0,0))+scale_x_continuous(limits=c(0,max(wm$power)*1.08),breaks=scales::pretty_breaks(3))+coord_cartesian(ylim=c(-1/24,4+1/24),expand=FALSE)+labs(x='Mean power',y=NULL,tag=letters[(k-1)*3+3])+base+theme(axis.ticks.y=element_blank(),axis.line.y=element_blank())
 parts<-c(parts,list(a,plot_spacer(),b,g))
}
p<-wrap_plots(parts,ncol=2,widths=c(4.8,1),heights=c(.65,1.5,.65,1.5),guides='collect')&theme(legend.position='bottom')
savecase('WAVELET',p,wd,list(power=wp,mean_power=wm,cone=wc),183,163,
 '固定种子生成2条256时点的波形，dt=0.25h；WaveletComp1.2实际计算Morlet连续小波，周期1-16h、dj=1/12、无loess去趋势，make.pval=FALSE。两条件共用原生标准化功率色标；右侧均谱由同一功率矩阵按时间平均。灰白遮罩与虚线来自原生cone of influence；不展示显著性、不把模拟波形当作真实生理信号。',c(setNames(pc,paste0('power',1:5)),linecols),
