# Same normalized series feed the time traces, delay portraits, and Euclidean recurrence matrices.
set.seed(seed);n<-360;tt<-0:(n-1);types<-c('Periodic','Quasiperiodic','White noise');raw<-list(sin(2*pi*tt/48)+.05*rnorm(n),sin(2*pi*tt/48)+.6*sin(2*pi*tt/(48/sqrt(2)))+.04*rnorm(n),rnorm(n));rd<-ed<-rr<-lsm<-list();rp<-list();rcols<-c(Periodic='#397D7A',Quasiperiodic='#976A96','White noise'='#BC7D50');tau<-8L;eps<-.32
for(k in 1:3){
 v<-as.numeric(scale(raw[[k]]));type<-types[k];d<-data.frame(system=type,time_index=tt,value=v);rd[[k]]<-d;tkn<-nonlinearTseries::buildTakens(v,embedding.dim=2,time.lag=tau);e<-data.frame(system=type,index=seq_len(nrow(tkn))-1,x=tkn[,1],lagged=tkn[,2]);ed[[k]]<-e
 D<-as.matrix(dist(tkn));R<-D<=eps;ix<-which(R,arr.ind=TRUE);rr[[k]]<-data.frame(system=type,i=ix[,1]-1,j=ix[,2]-1,distance=D[ix]);rates<-sapply(1:120,function(l)mean(R[cbind(1:(nrow(R)-l),(1+l):nrow(R))]));lsm[[k]]<-data.frame(system=type,lag=1:120,recurrence_rate=rates)
 a<-ggplot(d,aes(time_index,value))+geom_line(colour=rcols[type],linewidth=.28)+scale_x_continuous(limits=c(0,359),breaks=c(0,120,240,360))+scale_y_continuous(limits=c(-3.5,3.5),breaks=c(-2,0,2))+labs(title=type,x='Time index',y=if(k==1)'Standardized signal'else NULL,tag=letters[k])+base
 b<-ggplot(e,aes(x,lagged))+geom_path(colour=rcols[type],linewidth=.22,alpha=if(k==3).25 else .65)+geom_point(data=e[1,],shape=21,fill='white',colour=rcols[type],size=1.7,stroke=.5)+coord_fixed(xlim=c(-3.5,3.5),ylim=c(-3.5,3.5))+scale_x_continuous(breaks=c(-2,0,2))+scale_y_continuous(breaks=c(-2,0,2))+labs(x='x(t)',y=if(k==1)'x(t + 8)'else NULL,tag=letters[k+3])+base
 c<-ggplot(rr[[k]],aes(i,j))+geom_tile(fill=rcols[type],width=1,height=1)+coord_fixed(xlim=c(-.5,351.5),ylim=c(-.5,351.5),expand=FALSE)+scale_x_continuous(breaks=c(0,100,200,300))+scale_y_continuous(breaks=c(0,100,200,300))+labs(x='Time index i',y=if(k==1)'Time index j'else NULL,tag=letters[k+6])+base+theme(panel.border=element_rect(fill=NA,colour='#879092',linewidth=.25),axis.line=element_blank())
 rp[[k]]<-list(a,b,c)
}
