# Native Hive axes: node order is pooled weighted-degree rank and is fixed across conditions.
set.seed(seed);classes<-c('Class A','Class B','Class C');nodes<-data.frame(name=sprintf('N%02d',1:54),class=factor(rep(classes,each=18),levels=classes));pairs<-t(combn(1:54,2));pairs<-pairs[nodes$class[pairs[,1]]!=nodes$class[pairs[,2]],];prob<-exp(-abs(((pairs[,1]-1)%%18)-((pairs[,2]-1)%%18))/5)*.5+.035;pick<-runif(nrow(pairs))<prob
edges<-data.frame(from=pairs[pick,1],to=pairs[pick,2]);edges$weight_a<-sample(1:5,nrow(edges),TRUE);edges$weight_b<-pmax(0,edges$weight_a+sample(-3:4,nrow(edges),TRUE));edges$pair<-paste(as.character(nodes$class[edges$from]),as.character(nodes$class[edges$to]),sep=' / ')
strength<-function(weight)vapply(1:54,function(i)sum(weight[edges$from==i|edges$to==i]),numeric(1));nodes$strength_a<-strength(edges$weight_a);nodes$strength_b<-strength(edges$weight_b);nodes$pooled<-nodes$strength_a+nodes$strength_b;nodes$rank<-ave(nodes$pooled,nodes$class,FUN=function(x)rank(x,ties.method='first'))
hc<-c('Class A'='#2D8E8C','Class B'='#B57950','Class C'='#8674A6');ec<-setNames(c('#62A6A6','#A58DBA','#CCAA83'),sort(unique(edges$pair)));np<-list();coords<-list()
for(k in 1:2){
 e<-edges;e$weight<-e[[c('weight_a','weight_b')[k]]];e<-e[e$weight>0,];g<-tidygraph::tbl_graph(nodes,e,directed=FALSE);lay<-ggraph::create_layout(g,layout='hive',axis=class,sort.by=rank,center.size=.12);coords[[k]]<-data.frame(condition=conds[k],name=lay$name,x=lay$x,y=lay$y,r=lay$r,rank=lay$rank)
 ends<-do.call(rbind,lapply(split(as.data.frame(lay),lay$class),function(z)z[which.max(z$r),]));ends$lx<-ends$x*1.18;ends$ly<-ends$y*1.13
 np[[k]]<-ggraph(lay)+geom_edge_hive(aes(edge_colour=pair,edge_width=weight),alpha=.32,show.legend=c(edge_width=TRUE,edge_colour=FALSE))+geom_axis_hive(aes(colour=class),label=FALSE,linewidth=.65,show.legend=FALSE)+geom_node_point(aes(colour=class),size=1.45,show.legend=FALSE)+geom_text(data=ends,aes(lx,ly,label=class),inherit.aes=FALSE,family='Arial',size=7/.pt)+scale_edge_colour_manual(values=ec)+scale_edge_width(range=c(.12,.75),limits=c(1,9),breaks=c(1,4,8),name='Edge weight',guide=guide_legend(override.aes=list(edge_alpha=1,edge_colour='#718087')))+scale_colour_manual(values=hc)+coord_fixed(xlim=c(-1.3,1.3),ylim=c(-.85,1.45),clip='off')+void+labs(title=conds[k],tag=letters[k])
}
coords<-do.call(rbind,coords);pr<-rbind(data.frame(nodes,condition=conds[1],strength=nodes$strength_a),data.frame(nodes,condition=conds[2],strength=nodes$strength_b));pr$condition<-factor(pr$condition,levels=conds)
profiles<-ggplot(pr,aes(rank,strength,colour=class,linetype=condition))+geom_line(linewidth=.4)+geom_point(size=.7)+facet_grid(~class)+scale_colour_manual(values=hc,guide='none')+scale_linetype_manual(values=c('solid','22'),name=NULL)+scale_x_continuous(breaks=c(1,6,12,18))+labs(x='Node rank by pooled strength',y='Weighted degree',tag='c')+base+theme(legend.position='bottom',strip.background=element_rect(fill='#F5F4F1',colour=NA),panel.spacing.x=unit(4,'mm'))
tot<-aggregate(cbind(weight_a,weight_b)~pair,edges,sum);names(tot)<-c('pair','condition_a','condition_b')
p<-((np[[1]]|np[[2]])/profiles)+plot_layout(heights=c(2.2,1),guides='collect')&theme(legend.position='bottom')
